package com.abyssredemption.abstool.client.serverstats.network.payload;
import com.abyssredemption.abstool.client.serverstats.model.TrendEntry; import net.minecraft.network.RegistryFriendlyByteBuf; import net.minecraft.network.codec.StreamCodec; import net.minecraft.network.protocol.common.custom.CustomPacketPayload; import net.minecraft.resources.Identifier; import java.util.*;
public record TrendResponsePayload(int protocolVersion,long requestId,int periodType,List<TrendEntry> entries) implements CustomPacketPayload { public static final Type<TrendResponsePayload> TYPE=new Type<>(Identifier.fromNamespaceAndPath("absservertool","trend_response")); public static final StreamCodec<RegistryFriendlyByteBuf,TrendResponsePayload> CODEC=StreamCodec.of((b,p)->{b.writeVarInt(p.protocolVersion);b.writeVarLong(p.requestId);b.writeVarInt(p.periodType);b.writeVarInt(p.entries.size());for(var e:p.entries){b.writeUtf(e.key(),16);b.writeVarInt(e.activePlayers());b.writeVarLong(e.playTimeTicks());b.writeVarLong(e.placements());b.writeVarLong(e.deaths());b.writeBoolean(e.complete());}},b->{int v=b.readVarInt();long r=b.readVarLong();int period=b.readVarInt();int n=b.readVarInt();if(n<0||n>90)throw new IllegalArgumentException("Invalid trend entry count");List<TrendEntry> es=new ArrayList<>(n);for(int i=0;i<n;i++)es.add(new TrendEntry(b.readUtf(16),b.readVarInt(),b.readVarLong(),b.readVarLong(),b.readVarLong(),b.readBoolean()));return new TrendResponsePayload(v,r,period,List.copyOf(es));}); public Type<? extends CustomPacketPayload> type(){return TYPE;} }
